using ClipBridge;
using QRCoder;
sealed class GroupWizard:Form
{
    private readonly GroupIdentity identity;private readonly bool joining;private DeviceGroup? existing;
    private readonly Func<string,GroupConnection,string,CancellationToken,Task<DeviceGroup>> create;
    private readonly Action save;private readonly Action<DeviceGroup> joined;private readonly Action<string> copy;
    private readonly CancellationTokenSource lifetime=new();private readonly System.Windows.Forms.Timer timer=new(){Interval=1500};private GroupSession? session;private bool polling;
    private readonly FlowLayoutPanel body=new(){Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false},inputs=new(){AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};
    private readonly List<Panel> fields=[];
    private readonly ComboBox transport=new(){DropDownStyle=ComboBoxStyle.DropDownList};private readonly TextBox address=new(){PlaceholderText="https://服务器地址:端口"},username=new(),password=new(){UseSystemPasswordChar=true},setup=new(){UseSystemPasswordChar=true},groupName=new(){Text="我的设备"},invitation=new(){PlaceholderText="16 位配对码，或粘贴完整邀请"};
    private readonly Label heading=BridgeWindow.MakeLabel("",20,FontStyle.Bold),feedback=BridgeWindow.MakeLabel("",10),safety=BridgeWindow.MakeLabel("",28,FontStyle.Bold),code=BridgeWindow.MakeLabel("",18,FontStyle.Bold),info=BridgeWindow.MakeLabel("",9);
    private readonly Button start=BridgeWindow.MakeButton("",true),confirm=BridgeWindow.MakeButton("安全码一致，确认",true),copyLink=BridgeWindow.MakeButton("复制邀请链接",false),copyCode=BridgeWindow.MakeButton("复制配对码",false);
    private readonly PictureBox qr=new(){SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.White,Size=new Size(210,210)};
    private Panel usernameRow=null!,passwordRow=null!,setupRow=null!;private readonly FlowLayoutPanel invitationBox=new(){AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Visible=false};
    public GroupWizard(GroupIdentity identity,bool joining,DeviceGroup? existing,Func<string,GroupConnection,string,CancellationToken,Task<DeviceGroup>> create,Action save,Action<DeviceGroup> joined,Action<string> copy){this.identity=identity;this.joining=joining;this.existing=existing;this.create=create;this.save=save;this.joined=joined;this.copy=copy;
        AppStyle.Dialog(this,joining?"加入同步组":"邀请设备",new Size(700,700));Controls.Add(body);
        heading.Text=joining?"加入同步组":"创建同步组";heading.Margin=new Padding(0,0,0,14);body.Controls.Add(heading);
        feedback.AutoSize=false;feedback.Height=76;feedback.Text="本机："+identity.Member.Name;feedback.Margin=new Padding(0,0,0,10);body.Controls.Add(feedback);
        body.Controls.Add(inputs);
        Panel Field(string title,Control input){var row=new Panel{Width=620,Height=56,TabIndex=fields.Count,TabStop=false};var label=BridgeWindow.MakeLabel(title,10);label.Location=new Point(0,12);row.Controls.Add(label);input.SetBounds(160,7,450,36);input.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;row.Controls.Add(input);inputs.Controls.Add(row);fields.Add(row);return row;}
        transport.Items.AddRange(["专用中转","WebDAV"]);transport.SelectedIndex=0;Field("连接方式",transport);Field("服务器 / 目录",address);usernameRow=Field("WebDAV账号",username);passwordRow=Field("WebDAV密码",password);
        if(joining)Field("配对码 / 邀请",invitation);else{Field("同步组名称",groupName);setupRow=Field("服务器管理码",setup);}
        info.AutoSize=false;info.Height=60;info.ForeColor=AppStyle.Muted;info.Text="手动加入：填写同一服务器地址和配对码。\nWebDAV 还需同一目录和账号；完整邀请可自动读取连接信息。";inputs.Controls.Add(info);
        start.Text=joining?"连接邀请":"创建并邀请";start.Size=new Size(200,44);start.Click+=async(_,_)=>await Begin();body.Controls.Add(start);AcceptButton=start;
        invitationBox.Margin=new Padding(0,12,0,12);invitationBox.Controls.Add(qr);code.AutoSize=false;code.Height=46;code.Font=new Font("Consolas",18,FontStyle.Bold);invitationBox.Controls.Add(code);
        var copies=new FlowLayoutPanel{Height=48,Width=400,WrapContents=false};copyCode.Size=new Size(150,40);copyLink.Size=new Size(165,40);copyCode.Click+=(_,_)=>{if(session is not null)copy(GroupPake.Display(session.Code));};copyLink.Click+=(_,_)=>{if(session is not null)copy(session.Link);};copies.Controls.Add(copyCode);copies.Controls.Add(copyLink);invitationBox.Controls.Add(copies);body.Controls.Add(invitationBox);
        safety.AutoSize=false;safety.Height=65;safety.Visible=false;body.Controls.Add(safety);confirm.Size=new Size(250,44);confirm.Visible=false;confirm.Click+=(_,_)=>{session?.Approve();confirm.Enabled=false;feedback.Text="已确认，等待对方确认。";};body.Controls.Add(confirm);
        var close=BridgeWindow.MakeButton("关闭",false);close.Size=new Size(120,42);close.Margin=new Padding(0,14,0,0);close.Click+=(_,_)=>Close();body.Controls.Add(close);CancelButton=close;
        void SizeBody(){int width=Math.Max(480,body.ClientSize.Width-22);foreach(Control child in body.Controls)if(child!=qr&&child is not Button)child.Width=width;foreach(var row in fields)row.Width=width-8;info.Width=width-8;code.Width=width-8;}
        body.Resize+=(_,_)=>SizeBody();SizeBody();transport.SelectedIndexChanged+=(_,_)=>Fields();Fields();timer.Tick+=async(_,_)=>await Poll();
        if(existing is not null){transport.SelectedIndex=existing.Connection.Transport=="webdav"?1:0;address.Text=existing.Connection.Server;username.Text=existing.Connection.Username;password.Text=existing.Connection.Password;groupName.Text=existing.Name;start.Text="生成邀请";heading.Text="邀请设备";foreach(Control row in inputs.Controls)row.Enabled=false;}
    }
    public void Prefill(GroupConnection connection){transport.SelectedIndex=connection.Transport=="webdav"?1:0;address.Text=connection.Server;username.Text=connection.Username;password.Text=connection.Password;}
    private void Fields(){bool dav=transport.SelectedIndex==1;inputs.SuspendLayout();inputs.Controls.SetChildIndex(usernameRow,2);inputs.Controls.SetChildIndex(passwordRow,3);usernameRow.Visible=dav;passwordRow.Visible=dav;if(setupRow is not null)setupRow.Visible=!dav;inputs.ResumeLayout(true);}
    private GroupConnection Connection(){var value=new GroupConnection{Transport=transport.SelectedIndex==1?"webdav":"relay",Server=address.Text.Trim().TrimEnd('/'),Username=username.Text.Trim(),Password=password.Text};value.Validate();return value;}
    private string Error(Exception e){if(e is ArgumentException or InvalidOperationException)return e.Message;if(e is System.Net.Http.HttpRequestException h){bool dav=existing?.Connection.Transport=="webdav"||transport.SelectedIndex==1;return h.StatusCode switch{System.Net.HttpStatusCode.Unauthorized=>dav?"WebDAV账号或应用密码不正确。":"服务器认证失败，请检查管理码或重新生成邀请。",System.Net.HttpStatusCode.Forbidden=>"服务器拒绝访问，请检查目录的读写权限。",System.Net.HttpStatusCode.TooManyRequests=>"服务器请求过于频繁，请稍后重试。",System.Net.HttpStatusCode.NotFound=>dav?"WebDAV 目录或邀请不存在，请检查地址。":"邀请不存在或已过期；请检查服务器地址与端口。",System.Net.HttpStatusCode.BadRequest=>dav?"WebDAV 拒绝目录或请求，请检查目录地址与权限。":"服务器拒绝邀请，请重新生成配对码。",_=>"连接失败，请检查网络和服务器地址。"};}return "设备验证失败，请重新生成邀请。";}
    private async Task Begin(){start.Enabled=false;feedback.Text="正在查找邀请，请稍候…";body.ScrollControlIntoView(feedback);try{session?.Dispose();timer.Stop();
            if(joining){string input=invitation.Text.Trim();GroupConnection connection;string value=input;if(input.StartsWith("clipbridge://group#",StringComparison.Ordinal)){var link=GroupRendezvous.Parse(input);connection=link.Connection;value=link.Code;}else{value=GroupPake.Normalize(input);connection=Connection();}session=await GroupSession.Join(connection,value,identity,joined,lifetime.Token);}
            else{existing??=await create(groupName.Text.Trim(),Connection(),setup.Text.Trim(),lifetime.Token);session=await GroupSession.Invite(existing,identity,save,lifetime.Token);code.Text=GroupPake.Display(session.Code);invitationBox.Visible=true;try{using var generator=new QRCodeGenerator();using var data=generator.CreateQrCode(session.Link,QRCodeGenerator.ECCLevel.L);using var renderer=new PngByteQRCode(data);using var stream=new MemoryStream(renderer.GetGraphic(4));using var image=Image.FromStream(stream);qr.Image?.Dispose();qr.Image=new Bitmap(image);}catch{qr.Visible=false;}}
            inputs.Visible=start.Visible=false;heading.Text=joining?"正在连接邀请设备":"等待新设备加入";feedback.Text="邀请五分钟内有效。安全码出现后，请在两端核对并确认。";body.AutoScrollPosition=Point.Empty;timer.Start();await Poll();
        }catch(Exception e){feedback.Text=Error(e);start.Enabled=true;body.ScrollControlIntoView(feedback);}}
    private async Task Poll(){if(polling||session is null||IsDisposed)return;polling=true;try{await session.Step(lifetime.Token);if(IsDisposed)return;timer.Interval=1500;feedback.Text=(session.Peer?.Name is{} name?name+"\n":"")+session.Status+"\n剩余 "+Math.Max(0,session.Expires-DateTimeOffset.UtcNow.ToUnixTimeSeconds())+" 秒";if(session.Ready){safety.Visible=confirm.Visible=true;safety.Text=session.Sas[..3]+" "+session.Sas[3..];confirm.Enabled=!session.Approved;heading.Text="核对两端安全码";body.ScrollControlIntoView(confirm);}if(session.Done){timer.Stop();confirm.Enabled=false;heading.Text="已加入同步组";feedback.Text=session.Status;copyCode.Enabled=copyLink.Enabled=false;}}
        catch(OperationCanceledException){}catch(System.Net.Http.HttpRequestException e){feedback.Text=Error(e)+"\n正在重试；邀请过期后请重新生成。";timer.Interval=e.StatusCode==System.Net.HttpStatusCode.TooManyRequests?15000:3000;}catch(Exception e){timer.Stop();confirm.Enabled=false;feedback.Text=Error(e);body.ScrollControlIntoView(feedback);}finally{polling=false;}}
    protected override void OnFormClosed(FormClosedEventArgs e){timer.Stop();timer.Dispose();lifetime.Cancel();session?.Dispose();qr.Image?.Dispose();base.OnFormClosed(e);}
}
